/* Persian root-aware instant search (offline-capable, no server).
 *
 * Data   : docs/data/api/search-index.json  (generated by scripts/build_search_index.py)
 * Engine : docs/assets/js/persian-stem.js   (+ persian-stem-data.js tables)
 *
 * What makes this different from a substring filter
 * -------------------------------------------------
 *  1. Morphology — «آجرکاری»، «آجرها» و «آجر» are the same headword family.
 *  2. Roots — a query for «بند» also finds «آب‌بندی»، «بندکشی»، «پشت‌بند»،
 *     «سیم آرماتوربندی», because the build pre-computed their roots.
 *  3. Half-space tolerance — «آب‌بندی»، «آب بندی» and «آببندی» are identical
 *     after folding, so users never lose a result to a keyboard habit.
 *  4. Field weighting — a hit in the headword beats a hit in the definition.
 *  5. Typo tolerance — one edit away, biased to Persian keyboard confusables.
 *  6. Multilingual — EN/FR/DE/AR columns are indexed too («rebar» → آرماتور).
 *
 * Security: results are built with createElement/textContent only. No string is
 * ever passed to innerHTML, so a hostile YAML value cannot become markup —
 * the same rule build_pages.py enforces server-side.
 */
(function () {
  "use strict";

  /* Match quality: how well a query token hit an indexed form. */
  var QUALITY = {
    exact: 1.0,
    stem: 0.95,
    root: 0.85,
    prefix: 0.6,
    reversePrefix: 0.55,
    fuzzy: 0.35,
    substring: 0.25
  };

  /* Headword matches are worth more than any other field hit. */
  var HEADWORD_BONUS = 1.5;
  /* A document that matches *every* query token is a real answer, not a guess. */
  var FULL_MATCH_BONUS = 1.6;

  var MAX_RESULTS = 25;
  var MAX_NEAR = 5;
  var NEAR_THRESHOLD = 3;
  var DEBOUNCE_MS = 110;

  var state = {
    index: null,
    lexicon: null,
    protected: null,
    vocabulary: [],
    loading: null,
    error: null
  };

  function hasOwn(obj, key) {
    return Object.prototype.hasOwnProperty.call(obj, key);
  }

  function Stem() {
    if (typeof window !== "undefined" && window.PersianStem) { return window.PersianStem; }
    if (typeof globalThis !== "undefined" && globalThis.PersianStem) { return globalThis.PersianStem; }
    if (typeof require === "function") {
      try { return require("./persian-stem.js"); } catch (err) { return null; }
    }
    return null;
  }

  function siteBaseUrl() {
    var bundle = document.querySelector('script[src*="assets/javascripts/bundle"]');
    if (bundle) {
      var idx = bundle.src.indexOf("assets/javascripts/");
      if (idx !== -1) { return bundle.src.slice(0, idx); }
    }
    return window.location.href.split("#")[0].split("?")[0].replace(/[^/]*$/, "");
  }

  function loadIndex() {
    if (state.loading) { return state.loading; }
    if (typeof fetch !== "function") {
      state.error = "no-fetch";
      return Promise.reject(state.error);
    }
    var url = siteBaseUrl() + "data/api/search-index.json";
    state.loading = fetch(url, { credentials: "same-origin" })
      .then(function (response) {
        if (!response.ok) { throw new Error("HTTP " + response.status); }
        return response.json();
      })
      .then(function (index) {
        var stem = Stem();
        state.index = index;
        state.lexicon = stem ? stem.lexiconSet(index.lexicon || []) : {};
        state.protected = stem ? stem.protectedSet(index.protected || []) : {};
        state.vocabulary = buildVocabulary(index, stem, state.lexicon, state.protected);
        return index;
      })
      .catch(function (err) {
        state.error = String(err && err.message ? err.message : err);
        state.loading = null;
        throw err;
      });
    return state.loading;
  }

  /* --------------------------------------------------------------------- */
  /* Ranking                                                                */
  /* --------------------------------------------------------------------- */

  function buildVocabulary(index, stem, lexicon, protectedSet) {
    /* Suggestion vocabulary = single words (root keys + headword tokens +
     * explicit synonyms). Whole headwords would never be one edit away from a
     * mistyped word, so typo help would silently never fire. */
    var words = {};
    Object.keys((index && index.roots) || {}).forEach(function (word) { words[word] = true; });
    (((index && index.terms) || [])).forEach(function (entry) {
      stem.tokenize(entry.fa || "").forEach(function (token) {
        words[stem.fold(token)] = true;
        words[stem.root(token, lexicon, protectedSet)] = true;
      });
      ["a"].forEach(function (key) {
        (((entry.f || {})[key]) || []).forEach(function (form) { words[form] = true; });
      });
    });
    return Object.keys(words).filter(function (word) { return word.length > 1; });
  }


  function prepareQuery(query) {
    var stem = Stem();
    var tokens = stem.tokenize(query);
    return tokens.map(function (token) {
      return {
        raw: token,
        folded: stem.fold(token),
        stem: stem.stem(token, state.lexicon, state.protected),
        root: stem.root(token, state.lexicon, state.protected)
      };
    }).filter(function (item) { return item.folded.length > 0; });
  }

  function fieldForms(entry, key) {
    return (entry.f && entry.f[key]) || [];
  }

  /* Prefix/typo tolerance is for *finding terms*, not for matching prose: a
   * three-letter query must not light up every definition containing
   * «اجرایی». Prose fields (definition, domain) therefore match on the exact,
   * stemmed or rooted form only. */
  var PREFIX_FIELDS = { t: true, a: true, e: true, r: true };

  function bestQuality(forms, token, key) {
    var set = forms.__set;
    if (!set) {
      set = {};
      forms.forEach(function (form) { set[form] = true; });
      forms.__set = set;
    }
    if (hasOwn(set, token.folded)) { return QUALITY.exact; }
    if (hasOwn(set, token.stem)) { return QUALITY.stem; }
    if (hasOwn(set, token.root)) { return QUALITY.root; }

    if (!PREFIX_FIELDS[key]) { return 0; }
    var best = 0;
    for (var i = 0; i < forms.length; i++) {
      var form = forms[i];
      if (form.length < 2 || token.folded.length < 2) { continue; }
      if (form.indexOf(token.folded) === 0) {
        if (QUALITY.prefix > best) { best = QUALITY.prefix; }
      } else if (token.folded.indexOf(form) === 0) {
        if (QUALITY.reversePrefix > best) { best = QUALITY.reversePrefix; }
      }
    }
    return best;
  }

  function fuzzyQuality(entry, token) {
    var stem = Stem();
    if (token.folded.length < 3) { return 0; }
    var candidates = fieldForms(entry, "t").concat(fieldForms(entry, "a"));
    for (var i = 0; i < candidates.length; i++) {
      var candidate = candidates[i];
      if (candidate.length < 3) { continue; }
      if (Math.abs(candidate.length - token.folded.length) > 1) { continue; }
      if (stem.editDistance(candidate, token.folded, 1) <= 1) { return QUALITY.fuzzy; }
      if (stem.editDistance(candidate, token.root, 1) <= 1) { return QUALITY.fuzzy; }
    }
    return 0;
  }

  function scoreEntry(entry, tokens, boosts) {
    /* Returns {score, matched, fuzzy}. Morphological hits are scored per field;
     * typo tolerance and substring matching are per-token fallbacks applied at
     * most once — otherwise a single fuzzy hit would be multiplied by the
     * number of fields and outrank an exact headword match. */
    var matched = 0;
    var fuzzyHits = 0;
    var total = 0;

    for (var i = 0; i < tokens.length; i++) {
      var token = tokens[i];
      var tokenBest = 0;

      Object.keys(boosts).forEach(function (key) {
        var forms = fieldForms(entry, key);
        if (!forms.length) { return; }
        var quality = bestQuality(forms, token, key);
        if (quality <= 0) { return; }
        var weight = boosts[key] * quality;
        if (key === "t") { weight *= HEADWORD_BONUS; }
        total += weight;
        if (weight > tokenBest) { tokenBest = weight; }
      });

      if (tokenBest === 0) {
        var fuzzy = fuzzyQuality(entry, token);
        if (fuzzy > 0) {
          total += boosts.t * fuzzy * HEADWORD_BONUS;
          fuzzyHits++;
          tokenBest = 1;
        }
      }
      if (tokenBest > 0) { matched++; }
    }

    return { score: total, matched: matched, fuzzy: fuzzyHits, tokens: tokens.length };
  }

  function search(query) {
    var stem = Stem();
    if (!stem || !state.index) { return null; }
    var tokens = prepareQuery(query);
    if (!tokens.length) {
      return { results: [], near: [], total: 0, tokens: [], suggestions: [], roots: [] };
    }
    var boosts = (state.index && state.index.fields) || { t: 10, a: 8, e: 6, r: 5, n: 2, d: 1 };

    var exact = [];
    var near = [];
    for (var i = 0; i < state.index.terms.length; i++) {
      var entry = state.index.terms[i];
      var scored = scoreEntry(entry, tokens, boosts);
      if (scored.matched === 0) { continue; }
      var score = scored.score;
      if (scored.matched === scored.tokens) { score *= FULL_MATCH_BONUS; }
      else { score *= scored.matched / scored.tokens; }
      /* Reviewed content outranks drafts on a tie — quality should be visible. */
      if (entry.st === "published") { score *= 1.08; }
      else if (entry.st === "reviewed") { score *= 1.04; }

      var hit = { entry: entry, score: score, fuzzy: scored.fuzzy };
      if (scored.fuzzy > 0 && scored.matched === scored.fuzzy) { near.push(hit); }
      else { exact.push(hit); }
    }

    function byScore(a, b) {
      if (b.score !== a.score) { return b.score - a.score; }
      return a.entry.fa < b.entry.fa ? -1 : a.entry.fa > b.entry.fa ? 1 : 0;
    }
    exact.sort(byScore);
    near.sort(byScore);

    /* Typo help: only for tokens that matched nothing at all. */
    var suggestions = [];
    tokens.forEach(function (token) {
      var hitToken = exact.concat(near).some(function (item) {
        return fieldForms(item.entry, "t").some(function (form) {
          return form === token.folded || form === token.root || form === token.stem;
        });
      });
      if (!hitToken) {
        stem.suggest(token.raw, state.vocabulary, 1, 3).forEach(function (word) {
          if (suggestions.indexOf(word) === -1) { suggestions.push(word); }
        });
      }
    });

    /* Same-root grouping, straight from the precomputed root map. */
    var roots = [];
    tokens.forEach(function (token) {
      [token.root, token.stem, token.folded].forEach(function (candidate) {
        if (candidate && hasOwn(state.index.roots || {}, candidate)) {
          var slugs = state.index.roots[candidate];
          if (slugs.length > 1 && roots.indexOf(candidate) === -1) { roots.push(candidate); }
        }
      });
    });

    /* Near misses are a courtesy, not an answer: show them only when the exact
     * set is thin, and never more than MAX_NEAR of them. */
    var results = exact.slice(0, MAX_RESULTS);
    if (results.length < NEAR_THRESHOLD) {
      results = results.concat(near.slice(0, MAX_NEAR));
    }
    return {
      results: results,
      near: near.slice(0, MAX_RESULTS),
      total: exact.length,
      nearTotal: near.length,
      tokens: tokens,
      suggestions: suggestions.slice(0, 3),
      roots: roots.slice(0, 3)
    };
  }

  /* --------------------------------------------------------------------- */
  /* Rendering (XSS-safe: createElement + textContent only)                 */
  /* --------------------------------------------------------------------- */

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) { node.className = className; }
    if (text !== undefined && text !== null) { node.textContent = text; }
    return node;
  }

  function markedText(parent, text, needles) {
    /* Split `text` on the first occurrences of any needle and wrap them in
     * <mark>. Everything goes through textContent, never innerHTML. */
    var remaining = String(text || "");
    var list = (needles || []).filter(Boolean).sort(function (a, b) {
      return b.length - a.length;
    });
    if (!list.length) { parent.appendChild(document.createTextNode(remaining)); return; }
    while (remaining.length) {
      var bestIndex = -1;
      var bestNeedle = "";
      for (var i = 0; i < list.length; i++) {
        var idx = remaining.toLowerCase().indexOf(list[i].toLowerCase());
        if (idx !== -1 && (bestIndex === -1 || idx < bestIndex)) {
          bestIndex = idx;
          bestNeedle = list[i];
        }
      }
      if (bestIndex === -1) {
        parent.appendChild(document.createTextNode(remaining));
        return;
      }
      if (bestIndex > 0) {
        parent.appendChild(document.createTextNode(remaining.slice(0, bestIndex)));
      }
      parent.appendChild(el("mark", "ps-mark", remaining.substr(bestIndex, bestNeedle.length)));
      remaining = remaining.slice(bestIndex + bestNeedle.length);
    }
  }

  function snippet(text, needles, budget) {
    budget = budget || 150;
    var folded = String(text || "");
    var first = -1;
    (needles || []).forEach(function (needle) {
      if (!needle) { return; }
      var idx = folded.toLowerCase().indexOf(needle.toLowerCase());
      if (idx !== -1 && (first === -1 || idx < first)) { first = idx; }
    });
    if (first === -1) {
      return folded.length > budget ? folded.slice(0, budget) + "…" : folded;
    }
    var start = Math.max(0, first - Math.floor(budget / 3));
    var slice = folded.slice(start, start + budget);
    return (start > 0 ? "…" : "") + slice + (start + budget < folded.length ? "…" : "");
  }

  var STATUS_FA = {
    draft: "پیش‌نویس",
    reviewed: "بازبینی‌شده",
    published: "منتشرشده"
  };
  var REVIEW_FA = {
    "ai-assisted": "بازبینی دستیار هوشمند",
    expert: "بازبینی متخصص",
    committee: "کمیتهٔ واژه‌گزینی"
  };

  function renderResults(container, outcome, query) {
    container.textContent = "";
    if (!outcome) { return; }

    var needles = [];
    outcome.tokens.forEach(function (token) {
      needles.push(token.folded, token.raw);
    });

    if (!outcome.results.length) {
      var empty = el("li", "ps-empty");
      empty.appendChild(el("p", null, "نتیجه‌ای برای «" + query + "» پیدا نشد."));
      if (outcome.suggestions.length) {
        var hint = el("p", "ps-suggest");
        hint.appendChild(document.createTextNode("شاید منظور شما: "));
        outcome.suggestions.forEach(function (word, index) {
          if (index) { hint.appendChild(document.createTextNode("، ")); }
          var button = el("button", "ps-chip", word);
          button.type = "button";
          button.setAttribute("data-query", word);
          hint.appendChild(button);
        });
      } else {
        empty.appendChild(
          el("p", "ps-hint", "جستجو ریشه‌محور است: «آجرکاری» با «آجر» و «بندکشی» با «بند» پیدا می‌شود.")
        );
      }
      if (outcome.suggestions.length) { empty.appendChild(hint); }
      container.appendChild(empty);
      return;
    }

    outcome.results.forEach(function (hit, position) {
      var entry = hit.entry;
      var isFuzzy = !!hit.fuzzy;
      var li = el("li", "ps-result" + (isFuzzy ? " ps-near" : ""));
      li.setAttribute("role", "option");
      li.id = "ps-opt-" + position;
      li.setAttribute("data-score", hit.score.toFixed(2));

      var head = el("div", "ps-result-head");
      var link = el("a", "ps-term", "");
      /* Absolute from the site root (derived from Material's bundle path), so
       * the same widget works on /, /terms/ and any nested page — and under a
       * project base path such as /eng-terms-fa/. */
      link.href = siteBaseUrl() + "terms/" + encodeURIComponent(entry.s) + "/";
      markedText(link, entry.fa, needles);
      head.appendChild(link);
      if (entry.en) {
        var en = el("span", "ps-en", entry.en);
        en.setAttribute("dir", "ltr");
        en.setAttribute("lang", "en");
        head.appendChild(en);
      }
      li.appendChild(head);

      var meta = el("div", "ps-result-meta");
      var statusText = STATUS_FA[entry.st] || entry.st;
      if (entry.st !== "draft" && entry.rl && REVIEW_FA[entry.rl]) {
        statusText += " — " + REVIEW_FA[entry.rl];
      }
      meta.appendChild(el("span", "ps-badge ps-badge-" + entry.st, statusText));
      if (isFuzzy) {
        meta.appendChild(el("span", "ps-badge ps-badge-near", "تطابق تقریبی"));
      }
      (entry.dom || []).forEach(function (domain) {
        meta.appendChild(el("span", "ps-domain", domain));
      });
      (entry.r || []).slice(0, 3).forEach(function (root) {
        var chip = el("button", "ps-chip ps-root", root);
        chip.type = "button";
        chip.setAttribute("data-query", root);
        chip.setAttribute("title", "جستجوی هم‌ریشه‌های «" + root + "»");
        meta.appendChild(chip);
      });
      li.appendChild(meta);

      if (entry.d) {
        li.appendChild(
          el("p", "ps-def", "")
        );
        markedText(li.lastChild, snippet(entry.d, needles), needles);
      }
      container.appendChild(li);
    });
  }

  /* --------------------------------------------------------------------- */
  /* Mounting                                                               */
  /* --------------------------------------------------------------------- */

  function mount(target) {
    if (target.dataset.persianSearchInit === "done") { return; }
    target.dataset.persianSearchInit = "done";

    var form = el("form", "ps-form");
    form.setAttribute("role", "search");
    form.setAttribute("autocomplete", "off");
    form.action = "";

    var labelId = "ps-label-" + Math.random().toString(36).slice(2, 8);
    var label = el("label", "ps-label", "جستجوی ریشه‌محور واژگان");
    label.setAttribute("for", labelId);
    form.appendChild(label);

    var input = el("input", "ps-input");
    input.type = "search";
    input.id = labelId;
    input.setAttribute("dir", "rtl");
    input.setAttribute("lang", "fa");
    input.setAttribute("spellcheck", "false");
    input.setAttribute("placeholder", "واژه، ریشه یا معادل لاتین… مثال: بند، آجرکاری، rebar");
    input.setAttribute("role", "combobox");
    input.setAttribute("aria-expanded", "false");
    input.setAttribute("aria-autocomplete", "list");
    input.setAttribute("aria-describedby", labelId + "-help");
    form.appendChild(input);

    var help = el(
      "p",
      "ps-help",
      "نیم‌فاصله اختیاری است: «آب‌بندی»، «آب بندی» و «آببندی» یک نتیجه می‌دهند. جمع، صفت تفضیلی و شکل فعل هم به ریشه برمی‌گردند."
    );
    help.id = labelId + "-help";
    form.appendChild(help);

    var status = el("div", "ps-status");
    status.setAttribute("aria-live", "polite");
    status.setAttribute("role", "status");
    form.appendChild(status);

    var results = el("ul", "ps-results");
    results.id = labelId + "-results";
    results.setAttribute("role", "listbox");
    results.setAttribute("aria-label", "نتایج جستجوی واژگان");
    input.setAttribute("aria-controls", results.id);
    form.appendChild(results);

    target.appendChild(form);

    var activeIndex = -1;

    function run(query) {
      if (!state.index) { return; }
      query = String(query || "").trim();
      if (!query) {
        results.textContent = "";
        status.textContent = "";
        input.setAttribute("aria-expanded", "false");
        return;
      }
      var outcome = search(query);
      renderResults(results, outcome, query);
      input.setAttribute("aria-expanded", outcome.results.length ? "true" : "false");
      if (!outcome) {
        status.textContent = "";
      } else {
        var parts = [outcome.total + " نتیجه"];
        if (outcome.nearTotal) { parts.push(outcome.nearTotal + " تطابق تقریبی"); }
        if (outcome.roots.length) { parts.push("ریشه: " + outcome.roots.join("، ")); }
        status.textContent = parts.join(" • ");
      }
      activeIndex = -1;
    }

    var timer = null;
    input.addEventListener("input", function () {
      if (timer) { window.clearTimeout(timer); }
      timer = window.setTimeout(function () { run(input.value); }, DEBOUNCE_MS);
    });

    form.addEventListener("submit", function (event) {
      event.preventDefault();
      run(input.value);
    });

    /* delegated click: root chips and suggestions re-run the search */
    form.addEventListener("click", function (event) {
      var node = event.target;
      while (node && node !== form) {
        if (node.getAttribute && node.getAttribute("data-query")) {
          event.preventDefault();
          input.value = node.getAttribute("data-query");
          run(input.value);
          input.focus();
          return;
        }
        node = node.parentNode;
      }
    });

    input.addEventListener("keydown", function (event) {
      var items = results.querySelectorAll("li.ps-result");
      if (!items.length) { return; }
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        var delta = event.key === "ArrowDown" ? 1 : -1;
        activeIndex = (activeIndex + delta + items.length) % items.length;
        for (var i = 0; i < items.length; i++) {
          items[i].classList.toggle("ps-active", i === activeIndex);
        }
        items[activeIndex].setAttribute("aria-selected", "true");
        input.setAttribute("aria-activedescendant", items[activeIndex].id);
        if (items[activeIndex].scrollIntoView) {
          items[activeIndex].scrollIntoView({ block: "nearest" });
        }
      } else if (event.key === "Enter" && activeIndex >= 0 && items[activeIndex]) {
        event.preventDefault();
        var link = items[activeIndex].querySelector("a");
        if (link) { window.location.href = link.href; }
      } else if (event.key === "Escape") {
        input.value = "";
        run("");
        input.setAttribute("aria-expanded", "false");
      }
    });

    function fail(reason) {
      status.textContent = "";
      results.textContent = "";
      var li = el("li", "ps-empty");
      li.appendChild(
        el(
          "p",
          null,
          reason === "no-fetch"
            ? "نمایهٔ جستجوی فارسی بارگذاری نشد؛ از جستجوی بالای صفحه استفاده کنید."
            : "نمایهٔ جستجوی فارسی در دسترس نیست. پس از mkdocs build دستور " +
                "python scripts/build_search_index.py را اجرا کنید."
        )
      );
      results.appendChild(li);
    }

    loadIndex().then(
      function () {
        input.disabled = false;
        if (input.value) { run(input.value); }
        /* deep link support: ?q=… runs the search immediately */
        if (typeof URLSearchParams === "function" && window.location.search) {
          var params = new URLSearchParams(window.location.search);
          var q = params.get("q");
          if (q) {
            input.value = q;
            run(q);
          }
        }
      },
      function () { fail(state.error || "load"); }
    );
  }

  function init() {
    if (!Stem()) {
      /* persian-stem.js failed to load (CSP, path, cache): degrade quietly. */
      return;
    }
    var targets = document.querySelectorAll("[data-persian-search]");
    for (var i = 0; i < targets.length; i++) { mount(targets[i]); }
  }

  if (typeof document === "undefined") {
    if (typeof module !== "undefined" && module.exports) {
      module.exports = {
        search: search,
        loadIndex: loadIndex,
        state: state,
        buildVocabulary: buildVocabulary
      };
    }
    return;
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
